mapper.select:
/* BmsPrintMapper.selectBmsInPrintList : 반입신고 출력용 추가 데이터 리스트 */ SELECT A.IN_NO , A.CARRYIN_DATE , A.BL_NO , A.CARGO_REFERENCE_NO , A.CD_TYPE , teoa.DROP_YN FROM TB_BMS_IN A WITH (NOLOCK) LEFT JOIN (SELECT OD_JOB_NO, DROP_YN FROM TB_ECM_OD_ADDITIONAL) teoa ON teoa.OD_JOB_NO = A.OD_JOB_NO WHERE 1=1
AND ${srchNoType} = REPLACE(#{srchNo}, '-', '')
AND A.STOCK_WT > 0

/* BmsPrintMapper.selectBmsSamplePrintList : 견본반출 출력용 추가 데이터 리스트 */
SELECT A.SAMPLE_NO , A.IN_NO , A.CARRYOUT_DATE , A.BL_NO , A.CARGO_REFERENCE_NO FROM TB_BMS_SAMPLE A LEFT JOIN TB_BMS_IN B WITH (NOLOCK) ON B.IN_NO = A.IN_NO WHERE 1=1
AND ${srchNoType} = REPLACE(#{srchNo}, '-', '')

/* BmsPrintMapper.selectBmsAbnormalPrintcontactNo : 수입검사이고반입 연락처 조회 */
SELECT
	SET_VALUE
FROM
	TB_SMS_ENT_BUS_OPTION
WHERE
	ENT_CODE = #{entCode}
	AND ENT_BUSINESS_CODE = #{entBusinessCode}
	AND OPTION_CODE = #{optionCode}
